export type EnglishBenefit = {
  title: string;
  amount: string;
  description: string;
  eligibility: string;
  period: string;
  contact: string;
};

const benefit = (
  title: string,
  amount: string,
  description: string,
  eligibility: string,
  period: string,
  contact: string,
): EnglishBenefit => ({ title, amount, description, eligibility, period, contact });

const birthGrant = (
  place: string,
  amount: string,
  contact: string,
  period: string,
  residence: string,
  description: string,
) =>
  benefit(
    `${place} Birth Grant`,
    amount,
    description,
    residence,
    period,
    contact,
  );

