// 2026-10-26 verification patches
import { EN_PATCHES, EN_REGION_NAMES, KO_PATCHES, CITY_NEUTRALIZE_EN } from "./patches-2026";
import { ORIGINAL_KO as KO_SOURCE } from "./benefits";
for (const [id, p] of Object.entries(EN_PATCHES)) { if (EN_BENEFITS[id]) Object.assign(EN_BENEFITS[id], p); }
// Mirror the Korean neutralisation for unconfirmed city entries (decided on the Korean source text).
for (const b of KO_SOURCE) {
  if (KO_PATCHES[b.id] || b.id.split("-").length !== 3) continue;
  const d = /\d/; const e = EN_BENEFITS[b.id];
  if (!e) continue;
  if (d.test(b.contact)) e.contact = "City/district office / community service center";
  if (!d.test(b.amount + b.description + b.eligibility + b.period)) continue;
  if (d.test(b.amount)) e.amount = CITY_NEUTRALIZE_EN.amount;
  e.description = ((e.description.split(/(?<=\.)\s+/).filter((x) => !d.test(x)).join(" ") || "Support related to " + e.title + ".") + CITY_NEUTRALIZE_EN.note).trim();
  if (d.test(b.eligibility)) e.eligibility = "Depends on your city/district (needs official confirmation)";
  if (d.test(b.period)) e.period = CITY_NEUTRALIZE_EN.period;
}
for (const [id, n] of Object.entries(EN_REGION_NAMES)) EN_REGIONS[id] = n;

